def solve_sensor_alarm(text):
    tokens = text.split()
    n, k, t = int(tokens[0]), int(tokens[1]), int(tokens[2])
    xs = [int(v) for v in tokens[3:3 + n]]
    if k > n:
        return '0'
    total = sum(xs[:k])
    count = 1 if total >= k * t else 0
    for i in range(k, n):
        total += xs[i] - xs[i - k]
        if total >= k * t:
            count += 1
    return str(count)
